import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const c=JSON.parse('{"title":"Welcome to VERA","description":"Get started with VERA — log hours, manage time off, and keep tabs on your projects from the console.","frontmatter":{"description":"Get started with VERA — log hours, manage time off, and keep tabs on your projects from the console."},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function s(i,e,h,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="welcome-to-vera" tabindex="-1">Welcome to VERA <a class="header-anchor" href="#welcome-to-vera" aria-label="Permalink to &quot;Welcome to VERA&quot;">​</a></h1><p>VERA is your team&#39;s time management tool. You work in the VERA console — a fast web app at <a href="https://app.getvera.site/console" target="_blank" rel="noreferrer">app.getvera.site</a> — to log your hours, manage time off, and (for managers and owners) keep an eye on how your projects and budgets are tracking.</p><p>No timesheets to wrestle with. No end-of-week scramble to remember what you did on Tuesday. You record work as you go, and everything stays in one place.</p><hr><h2 id="what-vera-does" tabindex="-1">What VERA does <a class="header-anchor" href="#what-vera-does" aria-label="Permalink to &quot;What VERA does&quot;">​</a></h2><p><strong>For team members:</strong> Log your hours as you work — pick the project, the type of work, and how long. Request time off and check where your requests stand. It takes seconds.</p><p><strong>For managers:</strong> See where your projects stand — hours logged, burn rates, and who&#39;s allocated to what. Approve time-off requests, manage allocations, and catch projects running ahead of schedule or close to budget.</p><p><strong>For owners:</strong> Everything managers see, plus the financial picture — revenue recognized, cost, margin — live, without opening a spreadsheet.</p><hr><h2 id="getting-in" tabindex="-1">Getting in <a class="header-anchor" href="#getting-in" aria-label="Permalink to &quot;Getting in&quot;">​</a></h2><p>Go to <a href="https://app.getvera.site/console" target="_blank" rel="noreferrer">app.getvera.site</a> and sign in with your work Google or Microsoft account. That&#39;s it — no separate password to remember.</p><p>What you see once you&#39;re in depends on your <a href="./roles.html">role</a>. Team members get the pages for their own time and time off; managers and owners get the full console.</p><hr><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p><strong>I need to log my hours</strong> → <a href="./logging-time.html">Logging time</a></p><p><strong>I need to request time off</strong> → <a href="./time-off.html">Time off</a></p><p><strong>I want to keep on top of my week</strong> → <a href="./morning-briefing.html">Your daily view</a></p><p><strong>I&#39;m not sure what I can see or do</strong> → <a href="./roles.html">Your role in VERA</a></p><p><strong>I need to understand projects and tasks</strong> → <a href="./projects.html">Projects and tasks</a></p><hr><h2 id="finding-your-way-around" tabindex="-1">Finding your way around <a class="header-anchor" href="#finding-your-way-around" aria-label="Permalink to &quot;Finding your way around&quot;">​</a></h2><p>The console has a simple side menu. As a team member you&#39;ll use:</p><p><strong>Time</strong> — log new hours and review everything you&#39;ve recorded.</p><p><strong>Time Off</strong> — request holiday or leave and track its status.</p><p><strong>Calendar</strong> — see your organization&#39;s company holidays.</p><p>Managers and owners see the rest of the console too — projects, clients, allocations, capacity, and reports.</p>',26)])])}const u=o(n,[["render",s]]);export{c as __pageData,u as default};
